<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {useUnsavedChanges} from '../composables/useUnsavedChanges'
import {auth} from '../auth'
import {modelApi} from '../api/models'
import ModelManager from '../components/ModelManager.vue'
const catalog=ref({profiles:[],allProfiles:[],connections:[],providers:[],systemEnabled:false,defaultModelId:''})
const loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),selected=ref([]),search=ref(''),legacy=ref(false)
const editing=ref(''),name=ref(''),provider=ref('openai'),baseUrl=ref(''),apiKey=ref(''),manualConnection=ref(''),manualModel=ref(''),manualName=ref('')
const connectionBaseline=ref(''), selectionBaseline=ref('')
const connectionSignature=()=>JSON.stringify([editing.value,name.value,provider.value,baseUrl.value])
const connectionDirty=computed(()=>!!connectionBaseline.value&&(connectionSignature()!==connectionBaseline.value||!!apiKey.value))
const dirty=computed(()=>connectionDirty.value||JSON.stringify([...selected.value].sort())!==selectionBaseline.value||!!manualModel.value||!!manualName.value)
const {allowDiscard}=useUnsavedChanges(dirty,busy, () => auth.user?.id || auth.user?.username)
const {allowDiscard:allowConnectionDiscard}=useUnsavedChanges(connectionDirty,busy, () => auth.user?.id || auth.user?.username)
onBeforeRouteLeave(()=>allowDiscard())
let generation=0,disposed=false
const owner=()=>auth.user?.id||auth.user?.username
const safe=token=>!disposed&&token===generation
const all=computed(()=>catalog.value.allProfiles||catalog.value.profiles||[])
const filtered=computed(()=>all.value.filter(p=>(p.name+' '+p.model+' '+p.provider).toLowerCase().includes(search.value.toLowerCase())))
const legacyCatalog=computed(()=>({...catalog.value,profiles:all.value.filter(p=>!p.connectionId)}))
const insecure=location.protocol!=='https:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname)
function apply(value,preserve=false){const previous=[...selected.value];catalog.value=value;const saved=[...(value.systemEnabled!==false?['system']:[]),...value.profiles.map(p=>p.id)];selectionBaseline.value=JSON.stringify([...saved].sort());selected.value=preserve?previous:saved}
function preset(){const info=catalog.value.providers.find(p=>p.id===provider.value);baseUrl.value=info?.defaultBaseUrl||'';name.value=info?.name||'';apiKey.value=''}
function setEditor(connection){editing.value=connection?.id||'';provider.value=connection?.provider||catalog.value.providers[0]?.id||'openai';name.value=connection?.name||'';baseUrl.value=connection?.baseUrl||'';apiKey.value='';if(!connection)preset();connectionBaseline.value=connectionSignature()}
async function edit(connection){if(await allowConnectionDiscard())setEditor(connection)}
async function load(){const token=++generation;loading.value=true;error.value='';try{const value=await modelApi.list();if(safe(token)){apply(value,!!selectionBaseline.value&&JSON.stringify([...selected.value].sort())!==selectionBaseline.value);if(!editing.value&&!connectionDirty.value)setEditor(null)}}catch{if(safe(token))error.value='设置加载失败，请重试。'}finally{if(safe(token))loading.value=false}}
async function run(action,success,preserveSelection=true){if(busy.value)return;const token=generation;busy.value=true;error.value='';message.value='';try{const result=await action();if(!safe(token))return;const value=result?.profiles?result:await modelApi.list();if(safe(token)){apply(value,preserveSelection&&JSON.stringify([...selected.value].sort())!==selectionBaseline.value);message.value=success;return true}}catch{if(safe(token))error.value='操作未完成。请检查服务地址、权限或模型 ID 后重试；原选择没有被替换。'}finally{if(safe(token))busy.value=false}}
async function saveConnection(){if(!name.value.trim()||!baseUrl.value.trim()||(!editing.value&&!apiKey.value.trim()))return;const payload={name:name.value.trim(),provider:provider.value,baseUrl:baseUrl.value.trim(),apiKey:apiKey.value};const saved=await run(()=>editing.value?modelApi.updateConnection(editing.value,payload):modelApi.createConnection(payload),'连接已保存。现在获取模型列表，再勾选常用模型。');payload.apiKey='';apiKey.value='';if(saved)connectionBaseline.value=connectionSignature()}
async function discover(id){await run(()=>modelApi.discover(id),'模型列表已更新。新模型需勾选并保存后才会出现在对话中。')}
async function remove(id){if(editing.value===id&&!(await allowConnectionDiscard()))return;if(!confirm('删除此连接及其密钥？关联模型将不可用于新任务，历史记录保留。'))return;await run(()=>modelApi.removeConnection(id),'连接已删除，历史任务保留。');if(editing.value===id)setEditor(null)}
async function saveSelection(){const ids=[...selected.value];await run(()=>modelApi.select(ids),'可选模型已保存。各工作空间只显示这些模型。',false)}
async function addManual(){if(!manualConnection.value||!manualModel.value.trim())return;const saved=await run(()=>modelApi.create({connectionId:manualConnection.value,model:manualModel.value.trim(),name:manualName.value.trim()||manualModel.value.trim()}),'模型已添加，请勾选并保存。');if(saved){manualModel.value='';manualName.value=''}}
watch(owner,()=>{connectionBaseline.value='';selectionBaseline.value='';name.value='';baseUrl.value='';manualConnection.value='';manualModel.value='';manualName.value='';editing.value='';apiKey.value='';legacy.value=false;catalog.value={profiles:[],allProfiles:[],connections:[],providers:[],systemEnabled:false,defaultModelId:''};selected.value=[];busy.value=false;message.value='';load()},{immediate:true})
onBeforeUnmount(()=>{disposed=true;generation++;apiKey.value=''})
</script>
<template>
 <main class="settings-page" data-testid="model-settings"><header><div><p class="eyebrow">个人设置</p><h1>模型与连接</h1><p>在这里保存 API Key，选择要在 Chat、Work 和 Coding 中使用的模型。</p></div><RouterLink to="/assistant?mode=chat">返回通用助手 →</RouterLink></header>
 <p v-if="loading" role="status">正在加载设置…</p><p v-if="error" class="notice error" role="alert">{{error}} <button @click="load" :disabled="busy">重新加载</button></p><p v-if="message" class="notice" role="status">{{message}}</p>
 <template v-if="!loading"><section class="settings-card"><h2>1. 连接模型服务</h2><p>每个服务连接保存一份密钥。密钥不会回显，也不会放进浏览器存储。</p><p v-if="insecure" class="notice error">当前连接未加密，请使用 HTTPS 后再填写真实 API Key。</p>
 <div class="connection-layout"><div class="connections"><button class="new-connection" @click="edit(null)" :disabled="busy" data-testid="connection-add">＋ 添加连接</button><article v-for="connection in catalog.connections" :key="connection.id" :class="{active:editing===connection.id}"><button class="connection-title" @click="edit(connection)" :disabled="busy"><strong>{{connection.name}}</strong><small>{{connection.provider}} · {{connection.hasKey?'密钥已保存':'未配置密钥'}}</small><small>{{connection.baseUrl}}</small></button><div class="connection-actions"><button :disabled="busy||!connection.hasKey" @click="discover(connection.id)" :data-testid="'discover-'+connection.id">获取模型</button><button :disabled="busy" @click="remove(connection.id)">删除</button></div></article><p v-if="!catalog.connections?.length">尚未添加服务连接。</p></div>
 <form class="connection-form" @submit.prevent="saveConnection"><h3>{{editing?'编辑连接':'添加连接'}}</h3><label>连接名称<input v-model="name" maxlength="80" required data-testid="connection-name" :disabled="busy"/></label><label>服务商<select v-model="provider" @change="preset" data-testid="connection-provider" :disabled="busy"><option v-for="p in catalog.providers" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>API 地址<input v-model="baseUrl" type="url" required maxlength="2048" placeholder="https://api.example.com/v1" data-testid="connection-base-url" :disabled="busy"/></label><label>API Key<input v-model="apiKey" type="password" autocomplete="new-password" spellcheck="false" :required="!editing" maxlength="8192" :placeholder="editing?'留空保留已有密钥':'仅保存到当前账号'" data-testid="connection-api-key" :disabled="busy"/></label><button class="primary" :disabled="busy" data-testid="connection-save">{{busy?'处理中…':'保存连接'}}</button></form></div>
 </section>
 <section class="settings-card"><div class="section-heading"><div><h2>2. 勾选常用模型</h2><p>建议选择约 6 个。只显示所勾选的模型，不限制为 6 个。获取列表不会调用生成模型。</p></div><span class="count" data-testid="selected-count">已选 {{selected.length}} 个</span></div><input v-model="search" class="model-search" placeholder="搜索模型名称或 ID" aria-label="搜索模型"/><div class="model-grid"><label class="model-choice"><input v-model="selected" value="system" type="checkbox" :disabled="busy" data-testid="select-system"/><span><strong>系统默认模型</strong><small>使用部署时配置的服务</small></span></label><label v-for="p in filtered" :key="p.id" class="model-choice"><input v-model="selected" :value="p.id" type="checkbox" :disabled="busy" :data-testid="'select-'+p.id"/><span><strong>{{p.name}}</strong><small>{{p.model}}</small><small>{{p.provider}} · {{p.reasoningEfforts?.length?'可调推理强度':'未提供可调强度'}}</small></span></label></div><p v-if="!all.length" class="empty">先保存连接并点击“获取模型”。服务未提供列表时，可在下方手动添加模型 ID。</p><div class="selection-actions"><button class="primary" :disabled="busy||!selected.length" @click="saveSelection" data-testid="selection-save">保存可选模型</button><small>至少保留一个。取消勾选不会删除历史任务。</small></div>
 <details class="manual-model"><summary>服务未提供模型列表？手动添加模型 ID</summary><form @submit.prevent="addManual"><label>服务连接<select v-model="manualConnection" required :disabled="busy" data-testid="manual-connection"><option value="" disabled>选择已保存连接</option><option v-for="c in catalog.connections" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>模型 ID<input v-model="manualModel" required maxlength="200" :disabled="busy" data-testid="manual-model"/></label><label>显示名称（选填）<input v-model="manualName" maxlength="80" :disabled="busy"/></label><button :disabled="busy||!manualConnection||!manualModel.trim()">添加模型</button></form></details>
 <button v-if="legacyCatalog.profiles.length" class="legacy-button" :disabled="busy" @click="legacy=true">管理旧版单模型配置（{{legacyCatalog.profiles.length}}）</button>
 </section>
 <section class="settings-card"><h2>3. 默认模型与推理强度</h2><label class="default-model">新空间的默认模型<select :value="catalog.defaultModelId" :disabled="busy" @change="run(()=>modelApi.setDefault($event.target.value),'默认模型已更新；已有空间选择保持。')" data-testid="default-model"><option v-if="catalog.systemEnabled!==false" value="system">系统默认模型</option><option v-for="p in catalog.profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label><p>推理强度在对话输入区选择，各空间分别记住。只显示服务明确支持的档位；更高强度可能增加耗时与用量，不保证答案更好。模型列表代表该服务返回的可见模型，不保证每个模型都适合当前任务。</p></section></template>
 <ModelManager v-if="legacy" :catalog="legacyCatalog" @close="legacy=false" @changed="load"/>
 </main>
</template>
<style scoped>
.settings-page{max-width:1240px;margin:auto;padding:42px 38px 70px;color:#29384a}.settings-page header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.settings-page h1{font-size:30px;margin:6px 0 12px}.eyebrow{font-size:12px;color:#65859a;letter-spacing:2px}.settings-page p{font-size:13px;line-height:1.8;color:#728092}.settings-page a{font-size:13px;color:#356b91;white-space:nowrap}.settings-card{padding:25px;border:1px solid #e1e7ee;border-radius:16px;background:#fff;margin:18px 0}.settings-card h2{font-size:18px;margin-bottom:8px}.settings-card h3{font-size:15px}.connection-layout{display:grid;grid-template-columns:1fr 1.1fr;gap:28px;margin-top:22px}.settings-page button{border:1px solid #d9e3eb;border-radius:8px;background:#f6f9fc;padding:9px 13px;color:#355570;font-size:13px}.settings-page button:disabled{opacity:.5;cursor:default}.settings-page button.primary{background:#285e78;border-color:#285e78;color:white}.connections article{border:1px solid #e1e7ee;border-radius:10px;margin-top:10px;padding:12px}.connections article.active{border-color:#74a1b5;background:#f7fbfc}.connections .connection-title{display:block;border:0;background:none;padding:0;width:100%;text-align:left}.connection-title small{display:block;margin-top:5px;color:#7d8795;overflow-wrap:anywhere}.connection-actions{display:flex;gap:8px;margin-top:12px}.connection-form{display:flex;flex-direction:column;gap:13px}.settings-page label{font-size:12px;color:#697888}.connection-form label{display:flex;flex-direction:column;gap:6px}.settings-page input:not([type=checkbox]),.settings-page select{width:100%;min-width:0;border:1px solid #dce4eb;background:#fff;border-radius:7px;padding:10px;color:#283d50;font-size:13px}.section-heading{display:flex;justify-content:space-between;align-items:start;gap:12px}.count{white-space:nowrap;background:#edf4f7;color:#345f74;padding:6px 11px;border-radius:20px;font-size:12px}.model-search{margin:18px 0}.model-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;max-height:440px;overflow:auto}.model-choice{display:flex;align-items:start;gap:10px;padding:12px;border:1px solid #e1e7ee;border-radius:9px;cursor:pointer}.model-choice:has(input:checked){border-color:#8eafc0;background:#f4f9fb}.model-choice input{margin-top:3px;accent-color:#285e78}.model-choice span{min-width:0;overflow-wrap:anywhere}.model-choice strong{color:#33475c;font-size:13px}.model-choice small{display:block;font-size:11px;margin-top:4px}.selection-actions{display:flex;align-items:center;gap:16px;margin-top:18px;flex-wrap:wrap}.selection-actions small{color:#89939f;font-size:11px}.manual-model{border-top:1px solid #edf0f3;margin-top:22px;padding-top:18px;font-size:12px;color:#55768b}.manual-model summary{cursor:pointer}.manual-model form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.manual-model label{display:flex;flex-direction:column;gap:6px}.legacy-button{margin-top:20px}.default-model{display:flex;align-items:center;gap:15px;margin:20px 0}.default-model select{max-width:350px}.notice{padding:12px 15px;border-radius:9px;background:#eaf3ee;margin:12px 0;color:#38664d!important}.notice.error{background:#fff1e9;color:#915634!important}.empty{padding:20px}.new-connection{width:100%}@media(max-width:760px){.settings-page{padding:24px 14px 50px}.settings-page header{align-items:start;flex-direction:column;gap:12px}.settings-page h1{font-size:25px}.settings-card{padding:18px 14px}.connection-layout{grid-template-columns:1fr}.model-grid{grid-template-columns:1fr}.section-heading{flex-wrap:wrap}.manual-model form{grid-template-columns:1fr}.default-model{align-items:start;flex-direction:column}.settings-page header p{max-width:100%}}
</style>
